export const money = (value: number | string | null | undefined) => new Intl.NumberFormat("fr-FR", { style: "currency", currency: "XOF", maximumFractionDigits: 0 }).format(Number(value ?? 0));
export const dateText = (value: Date | string | null | undefined) => value ? new Date(value).toLocaleDateString("fr-FR") : "—";

export function exportCsv(filename: string, columns: ExportColumn[], rows: ExportRow[]) {
  const content = buildCsvContent(columns, rows);
  const url = URL.createObjectURL(new Blob(["\uFEFF", content], { type: "text/csv;charset=utf-8" }));
  const anchor = document.createElement("a"); anchor.href = url; anchor.download = `${filename}.csv`; anchor.click(); URL.revokeObjectURL(url);
}
export function exportPdf(filename: string, title: string, columns: ExportColumn[], rows: ExportRow[]) {
  const pdf = new jsPDF({ orientation: "landscape", unit: "mm", format: "a4" });
  const margin = 12; const width = 297 - margin * 2; const columnWidth = width / Math.max(columns.length, 1); let y = 16;
  pdf.setFont("helvetica", "bold"); pdf.setFontSize(15); pdf.text(title, margin, y); y += 8;
  pdf.setFont("helvetica", "normal"); pdf.setFontSize(8); pdf.text(`Export du ${new Date().toLocaleString("fr-FR")}`, margin, y); y += 8;
  const header = () => { pdf.setFont("helvetica", "bold"); columns.forEach((column, index) => pdf.text(column.label.slice(0, 24), margin + index * columnWidth, y, { maxWidth: columnWidth - 2 })); y += 6; pdf.setFont("helvetica", "normal"); };
  header();
  rows.forEach(row => { if (y > 190) { pdf.addPage(); y = 16; header(); } columns.forEach((column, index) => pdf.text(String(row[column.key] ?? "—").slice(0, 42), margin + index * columnWidth, y, { maxWidth: columnWidth - 2 })); y += 6; });
  pdf.save(`${filename}.pdf`);
}
function ExportActions({ filename, title, columns, rows }: { filename: string; title: string; columns: ExportColumn[]; rows: ExportRow[] }) {
  return <div className="flex flex-wrap gap-2"><Button type="button" size="sm" variant="outline" onClick={() => exportCsv(filename, columns, rows)} disabled={!rows.length}>CSV</Button><Button type="button" size="sm" variant="outline" onClick={() => exportPdf(filename, title, columns, rows)} disabled={!rows.length}>PDF</Button></div>;
}

type PrintableReceipt = {
  receipt: { reference: string; qrPayload: string; integrityHash: string; issuedAt: Date | string; status: string };
  payment: { reference: string; netAmount: string | number };
  taxpayer?: { firstName?: string | null; lastName?: string | null; legalName?: string | null } | null;
};

type TaxpayerExportSource = { reference: string; type: "PERSON" | "COMPANY"; firstName?: string | null; lastName?: string | null; legalName?: string | null; status: string; createdAt: Date | string };
type ObligationExportSource = { obligation: { reference: string; dueDate: Date | string; expectedAmount: string | number; remainingAmount: string | number; status: string }; taxpayer?: PrintableReceipt["taxpayer"]; activity?: { label?: string | null } | null };
type ReceiptExportSource = { receipt: PrintableReceipt["receipt"]; payment: PrintableReceipt["payment"]; taxpayer?: PrintableReceipt["taxpayer"] };
type ReportExportSource = { byAgent: Array<{ label: string; amount: string | number }>; bySector: Array<{ label: string; amount: string | number }>; byTax: Array<{ label: string; amount: string | number }> };

export function buildTaxpayerExportRows(rows: TaxpayerExportSource[]): ExportRow[] {
  return rows.map(row => ({ reference: row.reference, name: row.type === "COMPANY" ? row.legalName || "—" : `${row.lastName ?? ""} ${row.firstName ?? ""}`.trim() || "—", type: row.type === "COMPANY" ? "Personne morale" : "Personne physique", status: row.status, createdAt: dateText(row.createdAt) }));
}

export function buildObligationExportRows(rows: ObligationExportSource[]): ExportRow[] {
  return rows.map(({ obligation, taxpayer, activity }) => ({ reference: obligation.reference, taxpayer: taxpayer?.legalName || `${taxpayer?.lastName ?? ""} ${taxpayer?.firstName ?? ""}`.trim() || "—", activity: activity?.label || "—", dueDate: dateText(obligation.dueDate), expected: money(obligation.expectedAmount), remaining: money(obligation.remainingAmount), status: obligation.status }));
}

export function buildReceiptExportRows(rows: ReceiptExportSource[]): ExportRow[] {
  return rows.map(({ receipt, payment, taxpayer }) => ({ reference: receipt.reference, taxpayer: taxpayer?.legalName || `${taxpayer?.lastName ?? ""} ${taxpayer?.firstName ?? ""}`.trim() || "—", amount: money(payment.netAmount), issuedAt: dateText(receipt.issuedAt), status: receipt.status }));
}

export function buildReportExportRows(report?: ReportExportSource): ExportRow[] {
  if (!report) return [];
  return [...report.byAgent.map(row => ({ dimension: "Agent", label: row.label, amount: money(row.amount) })), ...report.bySector.map(row => ({ dimension: "Secteur", label: row.label, amount: money(row.amount) })), ...report.byTax.map(row => ({ dimension: "Taxe", label: row.label, amount: money(row.amount) }))];
}

export const TAXPAYER_EXPORT_COLUMNS: ExportColumn[] = [{ key: "reference", label: "Référence" }, { key: "name", label: "Redevable" }, { key: "type", label: "Type" }, { key: "status", label: "Statut" }, { key: "createdAt", label: "Créé le" }];
export const OBLIGATION_EXPORT_COLUMNS: ExportColumn[] = [{ key: "reference", label: "Référence" }, { key: "taxpayer", label: "Redevable" }, { key: "activity", label: "Activité" }, { key: "dueDate", label: "Échéance" }, { key: "expected", label: "À payer (XAF)" }, { key: "remaining", label: "Restant (XAF)" }, { key: "status", label: "État" }];
export const RECEIPT_EXPORT_COLUMNS: ExportColumn[] = [{ key: "reference", label: "Référence" }, { key: "taxpayer", label: "Redevable" }, { key: "amount", label: "Montant (XAF)" }, { key: "issuedAt", label: "Émis le" }, { key: "status", label: "État" }];
export const REPORT_EXPORT_COLUMNS: ExportColumn[] = [{ key: "dimension", label: "Dimension" }, { key: "label", label: "Libellé" }, { key: "amount", label: "Montant (XAF)" }];

function printReceiptInFrame({ receipt, payment, taxpayer }: PrintableReceipt) {
  const escapeHtml = (value: string | number | null | undefined) => String(value ?? "—").replace(/[&<>'"]/g, character => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;" })[character] ?? character);
  const taxpayerName = taxpayer?.legalName || `${taxpayer?.lastName ?? ""} ${taxpayer?.firstName ?? ""}`.trim() || "—";
  const frame = document.createElement("iframe");
  frame.title = `Impression ${receipt.reference}`;
  frame.setAttribute("aria-hidden", "true");
  frame.style.cssText = "position:fixed;right:0;bottom:0;width:1px;height:1px;border:0;opacity:0;pointer-events:none;";
  document.body.appendChild(frame);
  const doc = frame.contentDocument;
  if (!doc) { frame.remove(); window.print(); return; }
  doc.open();
  doc.write(`<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>${escapeHtml(receipt.reference)}</title><style>@page{size:80mm auto;margin:6mm}*{box-sizing:border-box}body{margin:0;color:#0f172a;font-family:Arial,sans-serif;font-size:11px}.receipt{width:68mm;margin:0 auto}.brand{border-bottom:2px solid #0f5cdb;padding-bottom:10px}.brand strong{display:block;color:#073b8c;font-size:15px;letter-spacing:.04em}.title{margin:14px 0 6px;text-align:center;color:#073b8c;font-size:17px;font-weight:800}.badge{display:inline-block;border-radius:999px;background:#eaf2ff;color:#073b8c;padding:4px 8px;font-weight:700}.amount{margin:14px 0;border-radius:10px;background:linear-gradient(135deg,#0a55c7,#1775e5);padding:14px;color:#fff;text-align:center;font-size:21px;font-weight:800}.line{display:flex;justify-content:space-between;gap:12px;border-bottom:1px dashed #cbd5e1;padding:7px 0}.label{color:#475569}.hash{margin-top:14px;overflow-wrap:anywhere;color:#475569;font-family:monospace;font-size:8px}.footer{margin-top:16px;border-top:1px solid #cbd5e1;padding-top:10px;text-align:center;color:#475569;font-size:9px}</style></head><body><main class="receipt"><header class="brand"><strong>MAIRIE DE LIBREVILLE</strong><span>Gestion des taxes municipales</span></header><h1 class="title">REÇU D’ENCAISSEMENT</h1><p style="text-align:center"><span class="badge">${escapeHtml(receipt.status)}</span></p><div class="line"><span class="label">Référence</span><strong>${escapeHtml(receipt.reference)}</strong></div><div class="line"><span class="label">Redevable</span><strong>${escapeHtml(taxpayerName)}</strong></div><div class="line"><span class="label">Date d’émission</span><strong>${escapeHtml(dateText(receipt.issuedAt))}</strong></div><div class="amount">${escapeHtml(money(payment.netAmount))}</div><div class="line"><span class="label">Paiement</span><strong>${escapeHtml(payment.reference)}</strong></div><p class="hash"><strong>QR de contrôle :</strong> ${escapeHtml(receipt.qrPayload)}</p><p class="hash"><strong>Empreinte d’intégrité :</strong> ${escapeHtml(receipt.integrityHash)}</p><footer class="footer">Document final immuable · Toute réimpression est enregistrée.</footer></main></body></html>`);
  doc.close();
  frame.onload = () => { frame.contentWindow?.focus(); frame.contentWindow?.print(); window.setTimeout(() => frame.remove(), 1200); };
}

function PageTitle({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: ReactNode }) {
  return <section className="relative mb-6 overflow-hidden rounded-3xl border border-blue-100 bg-[radial-gradient(circle_at_top_right,_rgba(191,219,254,.88),_transparent_38%),linear-gradient(135deg,_#ffffff,_#f1f6ff)] px-6 py-6 shadow-[0_12px_30px_rgba(30,64,175,.06)] md:px-7"><span className="absolute right-0 top-0 size-28 -translate-y-10 translate-x-8 rounded-full bg-blue-400/10 blur-2xl" /><div className="relative flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className="inline-flex rounded-full border border-blue-100 bg-white/90 px-3 py-1 text-[10px] font-bold uppercase tracking-[0.17em] text-blue-700 shadow-sm">{eyebrow}</p><h1 className="mt-3 text-3xl font-bold tracking-tight text-slate-950">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-600">{description}</p></div>{action && <div className="shrink-0">{action}</div>}</div></section>;
}

function EmptyState({ icon: Icon, title, text }: { icon: typeof UsersRound; title: string; text: string }) {
  return <div className="grid min-h-52 place-items-center rounded-2xl border border-dashed border-blue-200 bg-[linear-gradient(135deg,_#fff,_#f6f9ff)] px-6 text-center"><div><span className="mx-auto grid size-11 place-items-center rounded-xl bg-blue-100 text-blue-700 shadow-sm"><Icon className="size-5" /></span><h3 className="mt-3 font-semibold text-slate-900">{title}</h3><p className="mx-auto mt-1 max-w-sm text-sm text-slate-500">{text}</p></div></div>;
}

function ErrorBlock({ message }: { message?: string }) { return <div className="flex items-center gap-2 rounded-xl border border-amber-200 bg-amber-50 p-3 text-sm text-amber-800"><AlertCircle className="size-4 shrink-0" />{message || "La mairie doit être configurée pour accéder à ce module."}</div>; }

function TerritoryCard({ title, rows, Icon }: { title: string; rows: Array<{ id: string; name?: string | null; label?: string | null }>; Icon: typeof MapPinned }) {
  return <Card className="border-[#dce8e3]"><CardHeader><CardDescription>{title.toUpperCase()}</CardDescription><CardTitle className="text-3xl">{rows.length}</CardTitle></CardHeader><CardContent>{rows.length ? <div className="space-y-2">{rows.slice(0, 5).map(row => <div key={row.id} className="flex items-center gap-2 text-sm"><Icon className="size-3.5 text-[#0f5a4e]" /><span className="truncate">{row.name || row.label}</span></div>)}</div> : <p className="text-sm text-slate-500">Aucun élément.</p>}</CardContent></Card>;
}

export function TaxpayersPage() {
  const [search, setSearch] = useState(""); const [showForm, setShowForm] = useState(false); const [showMerge, setShowMerge] = useState(false); const [type, setType] = useState<"PERSON" | "COMPANY">("PERSON");
  const list = trpc.municipal.taxpayers.list.useQuery(search ? { search } : undefined); const utils = trpc.useUtils();
  const create = trpc.municipal.taxpayers.create.useMutation({ onSuccess: () => { toast.success("Redevable enregistré."); utils.municipal.taxpayers.list.invalidate(); setShowForm(false); }, onError: error => toast.error(error.message) });
  const merge = trpc.municipal.taxpayers.merge.useMutation({ onSuccess: () => { toast.success("Fusion administrative enregistrée et journalisée."); utils.municipal.taxpayers.list.invalidate(); setShowMerge(false); }, onError: error => toast.error(error.message) });
  const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); create.mutate({ type, firstName: String(data.get("firstName") || "") || undefined, lastName: String(data.get("lastName") || "") || undefined, legalName: String(data.get("legalName") || "") || undefined, nationalId: String(data.get("nationalId") || "") || undefined, taxId: String(data.get("taxId") || "") || undefined }); };
  const exportRows = buildTaxpayerExportRows(list.data ?? []);
  return <><PageTitle eyebrow="Registre unique" title="Redevables" description="Consultez le registre municipal, recherchez un identifiant et créez des personnes physiques ou morales avec contrôle de doublon côté serveur." action={<div className="flex flex-wrap gap-2"><ExportActions filename="registre-redevables" title="Registre des redevables" columns={TAXPAYER_EXPORT_COLUMNS} rows={exportRows} /><Button variant="outline" onClick={() => setShowMerge(!showMerge)}><ArrowRightLeft className="mr-2 size-4" />Fusionner</Button><Button onClick={() => setShowForm(!showForm)} className="bg-[#0f5a4e] hover:bg-[#0b493e]"><Plus className="mr-2 size-4" />Nouveau redevable</Button></div>} />
    {showForm && <Card className="mb-6 border-[#dce8e3]"><CardHeader><CardTitle>Enregistrer un redevable</CardTitle><CardDescription>Les références sont générées par la plateforme. Les identifiants nationaux et fiscaux sont contrôlés pour éviter les doublons.</CardDescription></CardHeader><CardContent><form onSubmit={submit} className="grid gap-4 md:grid-cols-3"><div><Label>Type</Label><div className="mt-2 flex gap-2"><Button type="button" variant={type === "PERSON" ? "default" : "outline"} onClick={() => setType("PERSON")}>Personne physique</Button><Button type="button" variant={type === "COMPANY" ? "default" : "outline"} onClick={() => setType("COMPANY")}>Personne morale</Button></div></div>{type === "PERSON" ? <><div><Label htmlFor="lastName">Nom</Label><Input id="lastName" name="lastName" required /></div><div><Label htmlFor="firstName">Prénom</Label><Input id="firstName" name="firstName" required /></div></> : <div className="md:col-span-2"><Label htmlFor="legalName">Raison sociale</Label><Input id="legalName" name="legalName" required /></div>}<div><Label htmlFor="nationalId">Identifiant national</Label><Input id="nationalId" name="nationalId" /></div><div><Label htmlFor="taxId">Identifiant fiscal</Label><Input id="taxId" name="taxId" /></div><div className="flex items-end"><Button type="submit" disabled={create.isPending}>{create.isPending ? "Enregistrement…" : "Enregistrer"}</Button></div></form></CardContent></Card>}
    {showMerge && <Card className="mb-6 border-amber-200 bg-amber-50/40"><CardHeader><CardTitle>Fusion administrative tracée</CardTitle><CardDescription>La source devient « fusionnée », ses activités et obligations sont rattachées à la cible, et le motif est conservé dans le journal d’audit.</CardDescription></CardHeader><CardContent><form className="grid gap-4 md:grid-cols-4 md:items-end" onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); merge.mutate({ sourceTaxpayerId: String(data.get("sourceTaxpayerId")), targetTaxpayerId: String(data.get("targetTaxpayerId")), reason: String(data.get("reason")) }); }}><div><Label>Redevable source</Label><select name="sourceTaxpayerId" required className="mt-1 h-10 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="">Sélectionner</option>{list.data?.filter(row => row.status === "ACTIVE").map(row => <option key={row.id} value={row.id}>{row.reference} · {row.legalName || `${row.lastName ?? ""} ${row.firstName ?? ""}`}</option>)}</select></div><div><Label>Redevable cible</Label><select name="targetTaxpayerId" required className="mt-1 h-10 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="">Sélectionner</option>{list.data?.filter(row => row.status === "ACTIVE").map(row => <option key={row.id} value={row.id}>{row.reference} · {row.legalName || `${row.lastName ?? ""} ${row.firstName ?? ""}`}</option>)}</select></div><div><Label htmlFor="mergeReason">Motif</Label><Input id="mergeReason" name="reason" minLength={5} required placeholder="Doublon confirmé…" /></div><Button type="submit" variant="outline" disabled={merge.isPending}>{merge.isPending ? "Fusion…" : "Confirmer la fusion"}</Button></form></CardContent></Card>}
    <Card className="border-[#dce8e3]"><CardHeader className="flex-row items-center justify-between space-y-0"><div><CardTitle>Répertoire des redevables</CardTitle><CardDescription>{list.data?.length ?? 0} résultat(s) visible(s)</CardDescription></div><div className="relative w-64"><Search className="absolute left-3 top-2.5 size-4 text-slate-400" /><Input value={search} onChange={event => setSearch(event.target.value)} placeholder="Nom, référence…" className="pl-9" /></div></CardHeader><CardContent>{list.error ? <ErrorBlock message={list.error.message} /> : list.isLoading ? <p className="text-sm text-slate-500">Chargement…</p> : !list.data?.length ? <EmptyState icon={UsersRound} title="Aucun redevable enregistré" text="Créez le premier redevable pour démarrer le cycle fiscal." /> : <Table><TableHeader><TableRow><TableHead>Référence</TableHead><TableHead>Redevable</TableHead><TableHead>Type</TableHead><TableHead>Statut</TableHead><TableHead>Créé le</TableHead></TableRow></TableHeader><TableBody>{list.data.map(row => <TableRow key={row.id}><TableCell className="font-mono text-xs text-[#0f5a4e]">{row.reference}</TableCell><TableCell className="font-medium">{row.type === "COMPANY" ? row.legalName : `${row.lastName ?? ""} ${row.firstName ?? ""}`}</TableCell><TableCell>{row.type === "COMPANY" ? "Personne morale" : "Personne physique"}</TableCell><TableCell><Badge variant="outline" className="border-emerald-200 bg-emerald-50 text-emerald-700">{row.status}</Badge></TableCell><TableCell>{dateText(row.createdAt)}</TableCell></TableRow>)}</TableBody></Table>}</CardContent></Card></>;
}

export function ActivitiesPage() {
  const list = trpc.municipal.activities.list.useQuery(); const taxpayers = trpc.municipal.taxpayers.list.useQuery(); const catalog = trpc.municipal.catalog.options.useQuery(); const territory = trpc.municipal.territory.tree.useQuery(); const utils = trpc.useUtils();
  const [showForm, setShowForm] = useState(false); const [locationType, setLocationType] = useState<"MARKET" | "ZONE" | "MARKET_LOCATION" | "MOBILE" | "CUSTOM">("MARKET");
  const create = trpc.municipal.activities.create.useMutation({ onSuccess: result => { toast.success(result.initialObligationCount ? `Activité enregistrée : ${result.initialObligationCount} obligation fiscale a été générée.` : "Activité enregistrée. Aucune règle fiscale compatible : utilisez Fiscalité pour l’affecter puis générer l’obligation."); utils.municipal.activities.list.invalidate(); utils.municipal.taxation.obligations.invalidate(); setShowForm(false); }, onError: error => toast.error(error.message) });
  const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); create.mutate({ taxpayerId: String(data.get("taxpayerId")), activityTypeId: String(data.get("activityTypeId")), label: String(data.get("label")), locationType, zoneId: locationType === "ZONE" ? String(data.get("zoneId")) : undefined, marketId: locationType === "MARKET" ? String(data.get("marketId")) : undefined, marketLocationId: locationType === "MARKET_LOCATION" ? String(data.get("marketLocationId")) : undefined, address: locationType === "CUSTOM" ? String(data.get("address") || "") || undefined : undefined, startedAt: new Date(String(data.get("startedAt"))) }); };
  return <><PageTitle eyebrow="Cycle d’exploitation" title="Activités" description="Chaque activité est rattachée à un redevable et conserve son historique de propriété, de localisation et de statut. Lorsqu’une règle journalière correspond au type et au marché, elle est affectée et génère immédiatement l’obligation initiale." action={<Button onClick={() => setShowForm(!showForm)} className="bg-[#0f5a4e] hover:bg-[#0b493e]"><Plus className="mr-2 size-4" />Nouvelle activité</Button>} />
    {showForm && <Card className="mb-6 border-[#dce8e3]"><CardHeader><CardTitle>Déclarer une activité</CardTitle><CardDescription>Une affectation territoriale active est contrôlée avant l’enregistrement. Si une règle fiscale journalière correspond au type d’activité et au marché choisi, elle est automatiquement affectée et son obligation du jour est créée.</CardDescription></CardHeader><CardContent><form onSubmit={submit} className="grid gap-4 md:grid-cols-3"><div><Label>Redevable</Label><select name="taxpayerId" required className="mt-2 h-10 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="">Sélectionner</option>{taxpayers.data?.filter(row => row.status === "ACTIVE").map(row => <option key={row.id} value={row.id}>{row.reference} · {row.legalName || `${row.lastName ?? ""} ${row.firstName ?? ""}`}</option>)}</select></div><div><Label>Type d’activité</Label><select name="activityTypeId" required className="mt-2 h-10 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="">Sélectionner</option>{catalog.data?.activityTypes.map(({ type, category }) => <option key={type.id} value={type.id}>{category.label} · {type.label}</option>)}</select></div><div><Label htmlFor="activityLabel">Libellé</Label><Input id="activityLabel" name="label" required className="mt-2" /></div><div><Label>Type de localisation</Label><select value={locationType} onChange={event => setLocationType(event.target.value as typeof locationType)} className="mt-2 h-10 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="MARKET">Marché</option><option value="MARKET_LOCATION">Emplacement</option><option value="ZONE">Zone</option><option value="MOBILE">Mobile</option><option value="CUSTOM">Adresse personnalisée</option></select></div>{locationType === "MARKET" && <div><Label>Marché</Label><select name="marketId" required className="mt-2 h-10 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="">Sélectionner</option>{territory.data?.markets.map(row => <option key={row.id} value={row.id}>{row.code} · {row.name}</option>)}</select></div>}{locationType === "MARKET_LOCATION" && <div><Label>Emplacement</Label><select name="marketLocationId" required className="mt-2 h-10 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="">Sélectionner</option>{territory.data?.locations.map(row => <option key={row.id} value={row.id}>{row.code} · {row.label}</option>)}</select></div>}{locationType === "ZONE" && <div><Label>Zone</Label><select name="zoneId" required className="mt-2 h-10 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="">Sélectionner</option>{territory.data?.zones.map(row => <option key={row.id} value={row.id}>{row.code} · {row.name}</option>)}</select></div>}{locationType === "CUSTOM" && <div><Label htmlFor="address">Adresse</Label><Input id="address" name="address" required className="mt-2" /></div>}<div><Label htmlFor="startedAt">Début d’activité</Label><Input id="startedAt" name="startedAt" type="date" defaultValue={new Date().toISOString().slice(0, 10)} required className="mt-2" /></div><div className="flex items-end"><Button type="submit" disabled={create.isPending}>{create.isPending ? "Enregistrement…" : "Enregistrer l’activité"}</Button></div></form></CardContent></Card>}
    <Card className="border-[#dce8e3]"><CardHeader><CardTitle>Registre des activités</CardTitle><CardDescription>Les types d’activité sont configurés dans l’administration avant la première affectation.</CardDescription></CardHeader><CardContent>{list.error ? <ErrorBlock message={list.error.message} /> : list.isLoading ? <p className="text-sm text-slate-500">Chargement…</p> : !list.data?.length ? <EmptyState icon={ArrowRightLeft} title="Aucune activité enregistrée" text="Les activités seront créées à partir d’un redevable et d’un type d’activité configuré." /> : <Table><TableHeader><TableRow><TableHead>Référence</TableHead><TableHead>Libellé</TableHead><TableHead>Redevable</TableHead><TableHead>Marché</TableHead><TableHead>Statut</TableHead></TableRow></TableHeader><TableBody>{list.data.map(({ activity, taxpayer, market }) => <TableRow key={activity.id}><TableCell className="font-mono text-xs text-[#0f5a4e]">{activity.reference}</TableCell><TableCell className="font-medium">{activity.label}</TableCell><TableCell>{taxpayer?.legalName || `${taxpayer?.lastName ?? ""} ${taxpayer?.firstName ?? ""}`}</TableCell><TableCell>{market?.name ?? activity.address ?? "—"}</TableCell><TableCell><Badge variant="outline">{activity.status}</Badge></TableCell></TableRow>)}</TableBody></Table>}</CardContent></Card></>;
}

function LegacyTerritoryPage() {
  const tree = trpc.municipal.territory.tree.useQuery(); const [showForm, setShowForm] = useState(false); const utils = trpc.useUtils(); const create = trpc.municipal.territory.createSector.useMutation({ onSuccess: () => { toast.success("Secteur ajouté."); setShowForm(false); utils.municipal.territory.tree.invalidate(); }, onError: error => toast.error(error.message) });
  const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); create.mutate({ code: String(data.get("code")), name: String(data.get("name")) }); };
  return <><PageTitle eyebrow="Référentiel géographique" title="Territoire" description="La structure opérationnelle suit l’ordre Mairie → Secteur → Zone → Marché → Emplacement. Les affectations d’agents sont contrôlées côté serveur." action={<Button onClick={() => setShowForm(!showForm)}><Plus className="mr-2 size-4" />Ajouter un secteur</Button>} />
    {showForm && <Card className="mb-6"><CardContent className="pt-6"><form onSubmit={submit} className="flex flex-wrap items-end gap-3"><div><Label htmlFor="code">Code</Label><Input id="code" name="code" required /></div><div><Label htmlFor="name">Nom du secteur</Label><Input id="name" name="name" required /></div><Button type="submit" disabled={create.isPending}>Enregistrer</Button></form></CardContent></Card>}
    {tree.error ? <ErrorBlock message={tree.error.message} /> : <div className="grid gap-5 lg:grid-cols-4"><TerritoryCard title="Secteurs" rows={tree.data?.sectors ?? []} Icon={MapPinned} /><TerritoryCard title="Zones" rows={tree.data?.zones ?? []} Icon={MapPinned} /><TerritoryCard title="Marchés" rows={tree.data?.markets ?? []} Icon={WalletCards} /><TerritoryCard title="Emplacements" rows={tree.data?.locations ?? []} Icon={ClipboardCheck} /></div>}</>;
}

function LegacyTaxationPage() {
  const obligations = trpc.municipal.taxation.obligations.useQuery();
  return <><PageTitle eyebrow="Exigibilité & suivi" title="Fiscalité et obligations" description="Les obligations périodiques conservent le montant attendu, les pénalités, remises et ajustements. Seul le restant dû évolue après chaque encaissement." />
    <Card className="border-[#dce8e3]"><CardHeader><CardTitle>Obligations fiscales</CardTitle><CardDescription>Les échéances, états et soldes sont calculés à partir des règles fiscales paramétrées.</CardDescription></CardHeader><CardContent>{obligations.error ? <ErrorBlock message={obligations.error.message} /> : obligations.isLoading ? <p className="text-sm text-slate-500">Chargement…</p> : !obligations.data?.length ? <EmptyState icon={FileText} title="Aucune obligation générée" text="Configurez les types de taxes, périodicités et règles tarifaires afin de générer les obligations." /> : <div className="overflow-x-auto"><Table className="min-w-[860px]"><TableHeader><TableRow><TableHead>Référence</TableHead><TableHead>Redevable</TableHead><TableHead>Activité</TableHead><TableHead>Échéance</TableHead><TableHead>Restant dû</TableHead><TableHead>État</TableHead></TableRow></TableHeader><TableBody>{obligations.data.map(({ obligation, taxpayer, activity }) => <TableRow key={obligation.id}><TableCell className="font-mono text-xs text-[#0f5a4e]">{obligation.reference}</TableCell><TableCell>{taxpayer?.legalName || `${taxpayer?.lastName ?? ""} ${taxpayer?.firstName ?? ""}`}</TableCell><TableCell>{activity?.label}</TableCell><TableCell>{dateText(obligation.dueDate)}</TableCell><TableCell className="font-semibold">{money(obligation.remainingAmount)}</TableCell><TableCell><Badge variant="outline">{obligation.status}</Badge></TableCell></TableRow>)}</TableBody></Table></div>}</CardContent></Card></>;
}

export function TerritoryPage() { return <TerritoryWorkspace />; }
export function TaxationPage() { return <TaxationWorkspace />; }

export function PaymentsPage() {
  const list = trpc.municipal.payments.list.useQuery(); const sync = trpc.municipal.sync.status.useQuery(); const obligations = trpc.municipal.taxation.obligations.useQuery(); const methods = trpc.municipal.payments.methods.useQuery(); const utils = trpc.useUtils(); const { online, queue, queueSize, enqueue, acknowledge } = useOfflineQueue();
  const [showForm, setShowForm] = useState(false); const [taxpayerId, setTaxpayerId] = useState(""); const [taxpayerSearch, setTaxpayerSearch] = useState(""); const [selectedTaxpayerLabel, setSelectedTaxpayerLabel] = useState(""); const [selectedObligationIds, setSelectedObligationIds] = useState<string[]>([]); const [allocations, setAllocations] = useState([{ methodId: "", amount: "" }]); const [selectedReceiptId, setSelectedReceiptId] = useState<string | null>(null); const [receiptMode, setReceiptMode] = useState<"ORIGINAL" | "REPRINT">("ORIGINAL");
  const taxpayerMatches = trpc.municipal.taxpayers.searchForPayment.useQuery({ query: taxpayerSearch.trim() }, { enabled: taxpayerSearch.trim().length >= 2 && online });
  const selectedObligations = useMemo(() => obligations.data?.filter(({ obligation }) => obligation.taxpayerId === taxpayerId && selectedObligationIds.includes(obligation.id)) ?? [], [obligations.data, taxpayerId, selectedObligationIds]); const obligationTotal = selectedObligations.reduce((sum, row) => sum + Number(row.obligation.remainingAmount), 0);
  const collect = trpc.municipal.payments.collect.useMutation({ onSuccess: result => { toast.success(`Encaissement validé · reçu ${result.receiptReference}`); utils.municipal.payments.list.invalidate(); utils.municipal.taxation.obligations.invalidate(); setSelectedReceiptId(result.receiptId ?? null); setReceiptMode("ORIGINAL"); setShowForm(false); setSelectedObligationIds([]); setPendingCollection(null); }, onError: error => toast.error(error.message) });
  const [pendingCollection, setPendingCollection] = useState<Parameters<typeof collect.mutate>[0] | null>(null);
  const selectedReceipt = list.data?.find(row => row.receipt?.id === selectedReceiptId);
  const reprintReceipt = trpc.municipal.payments.reprintReceipt.useMutation({ onSuccess: () => { if (selectedReceipt?.receipt) { printReceiptInFrame({ receipt: selectedReceipt.receipt, payment: selectedReceipt.payment, taxpayer: selectedReceipt.taxpayer }); toast.success("Réimpression enregistrée et envoyée à l’impression."); } }, onError: error => toast.error(error.message) });
  useEffect(() => { const pending = queue.find(operation => operation.entityType === "payment"); if (online && pending && !collect.isPending) collect.mutate(pending.payload as Parameters<typeof collect.mutate>[0], { onSuccess: () => acknowledge(pending.operationId) }); }, [online, queue, collect, acknowledge]);
  const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!taxpayerId || !selectedObligations.length) return toast.error("Sélectionnez un redevable et au moins une obligation."); const normalizedAllocations = allocations.filter(item => item.methodId && Number(item.amount) > 0).map(item => ({ paymentMethodId: item.methodId, amount: Number(item.amount) })); const allocationTotal = normalizedAllocations.reduce((sum, item) => sum + item.amount, 0); if (Math.abs(allocationTotal - obligationTotal) > 0.001) return toast.error("Le total des moyens de paiement doit être égal au total des obligations sélectionnées."); setPendingCollection({ taxpayerId, items: selectedObligations.map(({ obligation }) => ({ obligationId: obligation.id, amount: Number(obligation.remainingAmount) })), allocations: normalizedAllocations, collectedAt: new Date(), deviceId: getDeviceId(), offlineOperationId: crypto.randomUUID() }); };
  const confirmCollection = () => { if (!pendingCollection) return; if (!online) { const offlineOperationId = pendingCollection.offlineOperationId ?? crypto.randomUUID(); enqueue({ entityType: "payment", entityId: offlineOperationId, operation: "CREATE", payload: { ...pendingCollection, offlineOperationId } }); toast.info("Encaissement conservé localement et synchronisé au retour du réseau."); setPendingCollection(null); setShowForm(false); return; } collect.mutate(pendingCollection); };
  return <><PageTitle eyebrow="Collecte terrain" title="Encaissement & reçus" description="Une transaction peut affecter plusieurs obligations et plusieurs moyens de paiement. Chaque reçu final contient un instantané immuable, un QR code et un historique d’impression." action={<Button onClick={() => setShowForm(!showForm)} className="bg-[#0f5a4e] hover:bg-[#0b493e]"><Banknote className="mr-2 size-4" />Nouvel encaissement</Button>} />
    {showForm && <Card className="mb-6 border-[#dce8e3]"><CardHeader><CardTitle>Encaisser des obligations</CardTitle><CardDescription>Recherchez un redevable par référence, identifiant national, identifiant fiscal ou nom. Le total des moyens de paiement doit égaler les obligations choisies. Un aperçu non signé est obligatoire avant la validation définitive du reçu.</CardDescription></CardHeader><CardContent><form onSubmit={submit} className="space-y-5"><div className="max-w-2xl"><Label htmlFor="payment-taxpayer-search">Rechercher le redevable</Label><Input id="payment-taxpayer-search" value={taxpayerSearch} onChange={event => { setTaxpayerSearch(event.target.value); setTaxpayerId(""); setSelectedTaxpayerLabel(""); setSelectedObligationIds([]); setPendingCollection(null); }} placeholder="Référence, identifiant national, identifiant fiscal ou nom…" autoComplete="off" className="mt-2" />{!online && <p className="mt-2 text-xs text-amber-700">La recherche nécessite une connexion. Les encaissements déjà préparés restent disponibles hors connexion.</p>}{taxpayerSearch.trim().length > 0 && taxpayerSearch.trim().length < 2 && <p className="mt-2 text-xs text-slate-500">Saisissez au moins 2 caractères.</p>}{taxpayerMatches.isFetching && <p className="mt-2 text-xs text-slate-500">Recherche en cours…</p>}{taxpayerMatches.data && <div className="mt-2 overflow-hidden rounded-xl border border-blue-200 bg-white shadow-sm">{taxpayerMatches.data.length ? taxpayerMatches.data.map(row => { const label = row.legalName || `${row.lastName ?? ""} ${row.firstName ?? ""}`.trim() || row.reference; return <button key={row.id} type="button" onClick={() => { setTaxpayerId(row.id); setSelectedTaxpayerLabel(label); setTaxpayerSearch(row.reference); setSelectedObligationIds([]); setPendingCollection(null); }} className="flex w-full items-center justify-between gap-4 border-b border-slate-100 px-4 py-3 text-left last:border-b-0 hover:bg-blue-50"><span><span className="block font-semibold text-slate-950">{label}</span><span className="mt-1 block text-xs text-slate-500">{row.reference}{row.nationalId ? ` · ID national : ${row.nationalId}` : ""}{row.taxId ? ` · ID fiscal : ${row.taxId}` : ""}</span></span><span className="shrink-0 text-xs font-semibold text-blue-700">Choisir</span></button>; }) : <p className="p-4 text-sm text-slate-500">Aucun redevable actif ne correspond à cette recherche.</p>}</div>}{taxpayerId && <div className="mt-3 flex items-center justify-between rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-950"><span><strong>Redevable retenu :</strong> {selectedTaxpayerLabel || taxpayerSearch}</span><Button type="button" variant="ghost" size="sm" onClick={() => { setTaxpayerId(""); setSelectedTaxpayerLabel(""); setTaxpayerSearch(""); setSelectedObligationIds([]); }}>Modifier</Button></div>}</div><div><Label>Obligations à régler</Label><div className="mt-2 grid gap-2 md:grid-cols-2">{obligations.data?.filter(({ obligation }) => obligation.taxpayerId === taxpayerId && ["PENDING", "PARTIALLY_PAID", "OVERDUE"].includes(obligation.status)).map(({ obligation }) => <label key={obligation.id} className="flex items-center justify-between rounded-lg border border-[#dce8e3] bg-white p-3 text-sm"><span className="flex items-center gap-2"><input type="checkbox" checked={selectedObligationIds.includes(obligation.id)} onChange={event => { setPendingCollection(null); setSelectedObligationIds(current => event.target.checked ? [...current, obligation.id] : current.filter(id => id !== obligation.id)); }} />{obligation.reference}</span><span className="font-semibold">{money(obligation.remainingAmount)}</span></label>) || <p className="text-sm text-slate-500">Sélectionnez un redevable avec des obligations exigibles.</p>}</div></div><div><div className="mb-2 flex items-center justify-between"><Label>Moyens de paiement</Label><span className="text-sm font-semibold text-[#0f5a4e]">À affecter : {money(obligationTotal)}</span></div><div className="space-y-2">{allocations.map((allocation, index) => <div key={index} className="grid gap-2 sm:grid-cols-[1fr_180px_auto]"><select value={allocation.methodId} onChange={event => { setPendingCollection(null); setAllocations(current => current.map((row, rowIndex) => rowIndex === index ? { ...row, methodId: event.target.value } : row)); }} required className="h-10 rounded-md border border-input bg-background px-3 text-sm"><option value="">Moyen de paiement</option>{methods.data?.map(method => <option key={method.id} value={method.id}>{method.label}</option>)}</select><Input inputMode="decimal" value={allocation.amount} onChange={event => { setPendingCollection(null); setAllocations(current => current.map((row, rowIndex) => rowIndex === index ? { ...row, amount: event.target.value } : row)); }} placeholder="Montant" required /><Button type="button" variant="outline" disabled={allocations.length === 1} onClick={() => { setPendingCollection(null); setAllocations(current => current.filter((_, rowIndex) => rowIndex !== index)); }}>Retirer</Button></div>)}</div><Button type="button" variant="outline" className="mt-2" onClick={() => { setPendingCollection(null); setAllocations(current => [...current, { methodId: "", amount: "" }]); }}>Ajouter un moyen</Button></div><Button type="submit" disabled={collect.isPending}>{online ? "Voir l’aperçu avant validation" : "Voir l’aperçu hors connexion"}</Button></form>{pendingCollection && <div className="mt-6 rounded-2xl border-2 border-blue-200 bg-blue-50 p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-blue-700">Aperçu du reçu — non signé</p><h3 className="mt-1 text-lg font-bold text-slate-950">Contrôlez le montant avant validation</h3></div><Badge className="bg-amber-600">À confirmer</Badge></div><div className="mt-4 grid gap-3 text-sm sm:grid-cols-3"><p><span className="block text-slate-500">Obligations</span><strong>{pendingCollection.items.length} sélectionnée(s)</strong></p><p><span className="block text-slate-500">Paiement</span><strong>{money(pendingCollection.allocations.reduce((sum, item) => sum + Number(item.amount), 0))}</strong></p><p><span className="block text-slate-500">Statut</span><strong>{online ? "Prêt à émettre" : "À conserver localement"}</strong></p></div><div className="mt-5 flex flex-wrap gap-3"><Button type="button" className="bg-blue-700 hover:bg-blue-800" onClick={confirmCollection} disabled={collect.isPending}>{collect.isPending ? "Validation…" : online ? "Confirmer et émettre le reçu final" : "Confirmer et conserver hors connexion"}</Button><Button type="button" variant="outline" onClick={() => setPendingCollection(null)}>Modifier la saisie</Button></div></div>}</CardContent></Card>}
    {selectedReceiptId && <Card className="mb-5 border-2 border-blue-300 bg-blue-50 shadow-[0_14px_30px_rgba(30,64,175,.12)]"><CardHeader><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-blue-700">{receiptMode === "ORIGINAL" ? "Reçu final émis" : "Aperçu avant réimpression"}</p><CardTitle className="mt-1">{receiptMode === "ORIGINAL" ? "Remettez ce reçu au redevable" : "Réimprimer le reçu immuable"}</CardTitle><CardDescription>{receiptMode === "ORIGINAL" ? "Le paiement est validé : contrôlez le reçu puis imprimez-le séparément de la plateforme." : "Le contenu ne change pas. La réimpression sera inscrite dans son historique avant l’impression."}</CardDescription></div><Badge className={receiptMode === "ORIGINAL" ? "bg-emerald-700" : "bg-amber-700"}>{receiptMode === "ORIGINAL" ? "Prêt à imprimer" : "Traçable"}</Badge></div></CardHeader><CardContent>{!selectedReceipt?.receipt ? <p className="text-sm text-slate-600">Préparation du reçu final…</p> : <div className="grid gap-4 md:grid-cols-[1fr,auto]"><div className="rounded-xl border border-blue-200 bg-white p-4 text-sm"><p className="font-mono text-xs text-blue-700">{selectedReceipt.receipt.reference}</p><p className="mt-2 font-semibold text-slate-950">{selectedReceipt.taxpayer?.legalName || `${selectedReceipt.taxpayer?.lastName ?? ""} ${selectedReceipt.taxpayer?.firstName ?? ""}`.trim() || "Redevable"}</p><p className="mt-1 text-lg font-bold text-blue-900">{money(selectedReceipt.payment.netAmount)}</p><p className="mt-2 break-all text-xs text-slate-500">QR : {selectedReceipt.receipt.qrPayload}</p></div><div className="flex flex-col justify-center gap-2">{receiptMode === "ORIGINAL" ? <Button type="button" className="bg-blue-700 hover:bg-blue-800" onClick={() => { const receipt = selectedReceipt.receipt; if (!receipt) return; printReceiptInFrame({ receipt, payment: selectedReceipt.payment, taxpayer: selectedReceipt.taxpayer }); toast.success("Impression originale ouverte. Remettez le reçu au redevable."); }}><Printer className="mr-2 size-4" />Imprimer le reçu</Button> : <Button type="button" className="bg-blue-700 hover:bg-blue-800" disabled={reprintReceipt.isPending} onClick={() => { const receiptId = selectedReceipt.receipt?.id; if (receiptId) reprintReceipt.mutate({ receiptId, deviceId: getDeviceId() }); }}><Printer className="mr-2 size-4" />{reprintReceipt.isPending ? "Préparation…" : "Réimprimer ce reçu"}</Button>}<Button type="button" variant="outline" onClick={() => setSelectedReceiptId(null)}>Fermer l’aperçu</Button></div></div>}</CardContent></Card>}
    <div className="mb-5 grid gap-4 md:grid-cols-3"><Card><CardContent className="pt-6"><p className="text-xs font-bold uppercase tracking-[.14em] text-slate-500">Transactions</p><p className="mt-2 text-3xl font-semibold text-[#173931]">{list.data?.length ?? 0}</p></CardContent></Card><Card><CardContent className="pt-6"><p className="text-xs font-bold uppercase tracking-[.14em] text-slate-500">File de synchronisation</p><p className="mt-2 text-3xl font-semibold text-[#173931]">{online ? sync.data?.filter(row => row.status !== "SYNCED").length ?? 0 : queueSize}</p></CardContent></Card><Card><CardContent className="pt-6"><p className="text-xs font-bold uppercase tracking-[.14em] text-slate-500">Garantie d’intégrité</p><p className="mt-2 text-sm font-semibold text-emerald-700">Reçus finalisés non modifiables</p></CardContent></Card></div>
    <Card className="border-[#dce8e3]"><CardHeader><CardTitle>Historique d’encaissement</CardTitle><CardDescription>Chaque ligne permet de consulter son reçu, puis de le réimprimer avec une trace dans l’historique.</CardDescription></CardHeader><CardContent>{list.error ? <ErrorBlock message={list.error.message} /> : !list.data?.length ? <EmptyState icon={ReceiptText} title="Aucun encaissement" text="Les paiements validés et leurs reçus apparaîtront ici." /> : <div className="overflow-x-auto"><Table className="min-w-[780px]"><TableHeader><TableRow><TableHead>Paiement</TableHead><TableHead>Redevable</TableHead><TableHead>Montant</TableHead><TableHead>Date</TableHead><TableHead>État</TableHead><TableHead className="text-right">Reçu</TableHead></TableRow></TableHeader><TableBody>{list.data.map(({ payment, taxpayer, receipt }) => <TableRow key={payment.id}><TableCell className="whitespace-nowrap font-mono text-xs">{payment.reference}</TableCell><TableCell className="max-w-52 truncate">{taxpayer?.legalName || `${taxpayer?.lastName ?? ""} ${taxpayer?.firstName ?? ""}`}</TableCell><TableCell className="whitespace-nowrap font-semibold">{money(payment.netAmount)}</TableCell><TableCell className="whitespace-nowrap">{dateText(payment.collectedAt)}</TableCell><TableCell><Badge variant="outline">{payment.status}</Badge></TableCell><TableCell className="text-right">{receipt ? <Button type="button" size="sm" variant="outline" className="whitespace-nowrap" onClick={() => { setSelectedReceiptId(receipt.id); setReceiptMode("REPRINT"); }}><Eye className="mr-1.5 size-3.5" />Voir / réimprimer</Button> : "—"}</TableCell></TableRow>)}</TableBody></Table></div>}</CardContent></Card></>;
}

export function DepositsPage() {
  const list = trpc.municipal.deposits.list.useQuery(); const eligiblePayments = trpc.municipal.deposits.eligiblePayments.useQuery(); const utils = trpc.useUtils(); const declare = trpc.municipal.deposits.declare.useMutation({ onSuccess: result => { toast.success(`Versement déclaré. Écart : ${money(result.differenceAmount)}`); utils.municipal.deposits.list.invalidate(); utils.municipal.deposits.eligiblePayments.invalidate(); }, onError: error => toast.error(error.message) }); const validate = trpc.municipal.deposits.validate.useMutation({ onSuccess: () => { toast.success("Comptage validé."); utils.municipal.deposits.list.invalidate(); }, onError: error => toast.error(error.message) });
  return <><PageTitle eyebrow="Rapprochement" title="Versements & supervision" description="Les agents déclarent les versements à partir de paiements validés. Le contrôle de caisse et la validation conservent l’écart et l’identité du contrôleur." />
    <Card className="mb-5 border-[#dce8e3]"><CardHeader><CardTitle>Déclarer un versement</CardTitle><CardDescription>Sélectionnez les encaissements validés de la session, puis déclarez le montant effectivement remis. Un encaissement déjà rattaché à un versement est exclu et le serveur bloque toute double déclaration.</CardDescription></CardHeader><CardContent><form className="grid gap-4 lg:grid-cols-[1.4fr,1fr,auto] lg:items-end" onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); const paymentIds = data.getAll("paymentId").map(String); declare.mutate({ paymentIds, depositedAmount: Number(data.get("depositedAmount")), observation: String(data.get("observation")) || undefined }); }}><div><Label htmlFor="paymentIds">Encaissements éligibles</Label><select id="paymentIds" name="paymentId" multiple required disabled={!eligiblePayments.data?.length} className="mt-1 h-28 w-full rounded-md border border-input bg-background px-3 py-2 text-sm">{eligiblePayments.data?.map(row => <option key={row.payment.id} value={row.payment.id}>{row.payment.reference} · {row.taxpayer?.firstName ?? row.taxpayer?.legalName ?? "Redevable"} · {money(row.payment.netAmount)}</option>)}</select>{!eligiblePayments.isLoading && !eligiblePayments.data?.length && <p className="mt-2 text-sm text-slate-500">Aucun encaissement validé n’est disponible : les encaissements déjà versés ne peuvent pas être déclarés une seconde fois.</p>}</div><div className="grid gap-2"><div><Label htmlFor="depositedAmount">Montant remis</Label><Input id="depositedAmount" name="depositedAmount" type="number" min="0.01" step="0.01" required disabled={!eligiblePayments.data?.length} /></div><Input name="observation" placeholder="Observation éventuelle" disabled={!eligiblePayments.data?.length} /></div><Button type="submit" disabled={declare.isPending || !eligiblePayments.data?.length}>{declare.isPending ? "Déclaration…" : "Déclarer le versement"}</Button></form></CardContent></Card>
    <Card className="border-[#dce8e3]"><CardHeader><CardTitle>Versements déclarés</CardTitle></CardHeader><CardContent>{list.error ? <ErrorBlock message={list.error.message} /> : !list.data?.length ? <EmptyState icon={WalletCards} title="Aucun versement déclaré" text="Les versements soumis par les agents et les résultats de rapprochement seront visibles ici." /> : <Table><TableHeader><TableRow><TableHead>Référence</TableHead><TableHead>Attendu</TableHead><TableHead>Déposé</TableHead><TableHead>Écart</TableHead><TableHead>État</TableHead><TableHead className="text-right">Supervision</TableHead></TableRow></TableHeader><TableBody>{list.data.map(row => <TableRow key={row.id}><TableCell className="font-mono text-xs">{row.reference}</TableCell><TableCell>{money(row.expectedAmount)}</TableCell><TableCell>{money(row.depositedAmount)}</TableCell><TableCell className={Number(row.differenceAmount) === 0 ? "text-emerald-700" : "text-amber-700"}>{money(row.differenceAmount)}</TableCell><TableCell><Badge variant="outline">{row.status}</Badge></TableCell><TableCell className="text-right">{row.status === "SUBMITTED" && <Button size="sm" variant="outline" onClick={() => { const value = window.prompt("Montant compté", String(row.depositedAmount)); if (!value) return; validate.mutate({ depositId: row.id, countedAmount: Number(value), denominations: {} }); }} disabled={validate.isPending}>Compter / valider</Button>}</TableCell></TableRow>)}</TableBody></Table>}</CardContent></Card></>;
}

export function ClosingsPage() {
  const list = trpc.municipal.closings.list.useQuery(); const utils = trpc.useUtils(); const close = trpc.municipal.closings.close.useMutation({ onSuccess: result => { toast.success(`Clôture soumise. Écart : ${money(result.differenceAmount)}`); utils.municipal.closings.list.invalidate(); }, onError: error => toast.error(error.message) });
  return <><PageTitle eyebrow="Contrôle journalier" title="Clôtures comptables" description="La clôture quotidienne confronte les montants collectés et versés. Un écart reste visible, traçable et soumis à validation selon les droits de l’utilisateur." />
    <Card className="mb-5 border-[#dce8e3]"><CardHeader><CardTitle>Soumettre une clôture quotidienne</CardTitle><CardDescription>La clôture crée un état soumis : le montant attendu et le montant déclaré demeurent visibles, y compris en cas d’écart.</CardDescription></CardHeader><CardContent><form className="grid gap-4 md:grid-cols-4 md:items-end" onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); close.mutate({ businessDate: new Date(String(data.get("businessDate"))), expectedAmount: Number(data.get("expectedAmount")), depositedAmount: Number(data.get("depositedAmount")) }); }}><div><Label htmlFor="businessDate">Date d’activité</Label><Input id="businessDate" name="businessDate" type="date" defaultValue={new Date().toISOString().slice(0, 10)} required /></div><div><Label htmlFor="expectedAmount">Montant attendu</Label><Input id="expectedAmount" name="expectedAmount" type="number" min="0.01" step="0.01" required /></div><div><Label htmlFor="closingDepositedAmount">Montant versé</Label><Input id="closingDepositedAmount" name="depositedAmount" type="number" min="0.01" step="0.01" required /></div><Button type="submit" disabled={close.isPending}>{close.isPending ? "Soumission…" : "Soumettre la clôture"}</Button></form></CardContent></Card>
    <Card className="border-[#dce8e3]"><CardHeader><CardTitle>Historique des clôtures</CardTitle></CardHeader><CardContent>{list.error ? <ErrorBlock message={list.error.message} /> : !list.data?.length ? <EmptyState icon={ClipboardCheck} title="Aucune clôture" text="Les clôtures soumises par les agents seront disponibles ici." /> : <Table><TableHeader><TableRow><TableHead>Date</TableHead><TableHead>Attendu</TableHead><TableHead>Déposé</TableHead><TableHead>Écart</TableHead><TableHead>État</TableHead></TableRow></TableHeader><TableBody>{list.data.map(row => <TableRow key={row.id}><TableCell>{dateText(row.businessDate)}</TableCell><TableCell>{money(row.expectedAmount)}</TableCell><TableCell>{money(row.depositedAmount)}</TableCell><TableCell>{money(row.differenceAmount)}</TableCell><TableCell><Badge variant="outline">{row.status}</Badge></TableCell></TableRow>)}</TableBody></Table>}</CardContent></Card></>;
}

export function ReportsPage() {
  const [filters, setFilters] = useState<{ from?: Date; to?: Date }>({}); const report = trpc.municipal.reports.collectionSummary.useQuery(filters);
  const exportRows = buildReportExportRows(report.data);
  return <><PageTitle eyebrow="Analyse des recettes" title="Rapports de collecte" description="Les résultats respectent les droits d’accès applicables et ventilent les encaissements validés par agent, secteur, taxe et période." action={<ExportActions filename="rapport-recettes" title="Rapport des recettes" columns={REPORT_EXPORT_COLUMNS} rows={exportRows} />} />
    <Card className="mb-5 border-[#dce8e3]"><CardContent className="p-5"><form className="flex flex-col gap-3 md:flex-row md:items-end" onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); setFilters({ from: data.get("from") ? new Date(String(data.get("from"))) : undefined, to: data.get("to") ? new Date(`${String(data.get("to"))}T23:59:59`) : undefined }); }}><div><Label htmlFor="reportFrom">Du</Label><Input id="reportFrom" name="from" type="date" /></div><div><Label htmlFor="reportTo">Au</Label><Input id="reportTo" name="to" type="date" /></div><Button type="submit">Appliquer le filtre</Button></form></CardContent></Card>
    {report.error ? <ErrorBlock message={report.error.message} /> : <><section className="grid gap-4 sm:grid-cols-2"><Card className="border-[#dce8e3]"><CardContent className="p-5"><p className="text-xs font-bold uppercase tracking-[.13em] text-slate-500">Recettes validées</p><p className="mt-3 text-3xl font-semibold text-[#173931]">{report.isLoading ? "—" : money(report.data?.total)}</p></CardContent></Card><Card className="border-[#dce8e3]"><CardContent className="p-5"><p className="text-xs font-bold uppercase tracking-[.13em] text-slate-500">Lignes d’encaissement</p><p className="mt-3 text-3xl font-semibold text-[#173931]">{report.isLoading ? "—" : report.data?.transactionLines ?? 0}</p></CardContent></Card></section><section className="mt-5 grid gap-5 lg:grid-cols-3">{[{ title: "Par agent", rows: report.data?.byAgent ?? [] }, { title: "Par secteur", rows: report.data?.bySector ?? [] }, { title: "Par taxe", rows: report.data?.byTax ?? [] }].map(section => <Card key={section.title} className="border-[#dce8e3]"><CardHeader><CardTitle className="text-base">{section.title}</CardTitle></CardHeader><CardContent>{!section.rows.length ? <p className="text-sm text-slate-500">Aucune recette validée sur la période.</p> : <div className="space-y-3">{section.rows.map(row => <div key={row.label} className="flex items-center justify-between gap-3 border-b border-[#edf1ef] pb-3 last:border-0 last:pb-0"><span className="truncate text-sm text-slate-600">{row.label}</span><strong className="text-sm text-[#173931]">{money(row.amount)}</strong></div>)}</div>}</CardContent></Card>)}</section></>}
  </>;
}

type TerritorySelectionItem = { id: string; code: string; name?: string | null; label?: string | null };

function LegacyAdministrationPage() {
  const audit = trpc.municipal.audit.list.useQuery(); const sync = trpc.municipal.sync.status.useQuery(); const catalog = trpc.municipal.catalog.options.useQuery(); const territory = trpc.municipal.territory.tree.useQuery(); const adminUsers = trpc.municipal.administration.users.useQuery(); const roles = trpc.municipal.administration.roles.useQuery(); const permissions = trpc.municipal.administration.permissions.useQuery(); const territoryItems = ([...(territory.data?.sectors ?? []), ...(territory.data?.zones ?? []), ...(territory.data?.markets ?? []), ...(territory.data?.locations ?? [])] as TerritorySelectionItem[]); const utils = trpc.useUtils();
  const refreshed = (label: string) => () => { toast.success(`${label} enregistré.`); utils.municipal.catalog.options.invalidate(); };
  const createActivityCategory = trpc.municipal.catalog.createActivityCategory.useMutation({ onSuccess: refreshed("Catégorie d’activité"), onError: error => toast.error(error.message) }); const createActivityType = trpc.municipal.catalog.createActivityType.useMutation({ onSuccess: refreshed("Type d’activité"), onError: error => toast.error(error.message) }); const createTaxCategory = trpc.municipal.catalog.createTaxCategory.useMutation({ onSuccess: refreshed("Catégorie de taxe"), onError: error => toast.error(error.message) }); const createTaxType = trpc.municipal.catalog.createTaxType.useMutation({ onSuccess: refreshed("Type de taxe"), onError: error => toast.error(error.message) }); const createPeriodicity = trpc.municipal.catalog.createPeriodicity.useMutation({ onSuccess: refreshed("Périodicité"), onError: error => toast.error(error.message) }); const createPaymentMethod = trpc.municipal.catalog.createPaymentMethod.useMutation({ onSuccess: refreshed("Moyen de paiement"), onError: error => toast.error(error.message) });
  const refreshAdministration = (label: string) => () => { toast.success(`${label} enregistré.`); utils.municipal.administration.users.invalidate(); utils.municipal.administration.roles.invalidate(); utils.municipal.administration.permissions.invalidate(); }; const createRole = trpc.municipal.administration.createRole.useMutation({ onSuccess: refreshAdministration("Rôle"), onError: error => toast.error(error.message) }); const createPermission = trpc.municipal.administration.createPermission.useMutation({ onSuccess: refreshAdministration("Permission"), onError: error => toast.error(error.message) }); const assignRole = trpc.municipal.administration.assignRole.useMutation({ onSuccess: refreshAdministration("Affectation de rôle"), onError: error => toast.error(error.message) }); const setRolePermissions = trpc.municipal.administration.setRolePermissions.useMutation({ onSuccess: () => toast.success("Permissions du rôle mises à jour."), onError: error => toast.error(error.message) }); const assignTerritory = trpc.municipal.administration.assignTerritory.useMutation({ onSuccess: () => toast.success("Périmètre territorial affecté et historisé."), onError: error => toast.error(error.message) });
  return <><PageTitle eyebrow="Gouvernance" title="Administration, audit & synchronisation" description="Les rôles multiples, permissions par action, affectations territoriales et opérations de synchronisation constituent les contrôles de gouvernance de la plateforme." />
    <Card className="mb-5 border-[#dce8e3]"><CardHeader><CardTitle>Référentiels de démarrage</CardTitle><CardDescription>Configurez ces éléments avant de déclarer des activités, de créer des obligations ou d’encaisser. Aucun paramètre ne crée de donnée opérationnelle.</CardDescription></CardHeader><CardContent><div className="grid gap-6 xl:grid-cols-3"><div className="space-y-3 rounded-xl bg-[#f7f8f5] p-4"><p className="font-semibold text-[#173931]">Activités</p><form className="grid gap-2" onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); createActivityCategory.mutate({ code: String(data.get("code")), label: String(data.get("label")) }); event.currentTarget.reset(); }}><Input name="code" placeholder="Code catégorie" required /><Input name="label" placeholder="Libellé catégorie" required /><Button type="submit" size="sm" disabled={createActivityCategory.isPending}>Ajouter une catégorie</Button></form><form className="grid gap-2" onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); createActivityType.mutate({ categoryId: String(data.get("categoryId")), code: String(data.get("code")), label: String(data.get("label")) }); event.currentTarget.reset(); }}><select name="categoryId" required className="h-9 rounded-md border border-input bg-background px-3 text-sm"><option value="">Catégorie parente</option>{catalog.data?.activityCategories.map(row => <option key={row.id} value={row.id}>{row.label}</option>)}</select><Input name="code" placeholder="Code type" required /><Input name="label" placeholder="Libellé type" required /><Button type="submit" size="sm" variant="outline" disabled={createActivityType.isPending}>Ajouter un type</Button></form></div><div className="space-y-3 rounded-xl bg-[#f7f8f5] p-4"><p className="font-semibold text-[#173931]">Fiscalité</p><form className="grid gap-2" onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); createTaxCategory.mutate({ code: String(data.get("code")), label: String(data.get("label")) }); event.currentTarget.reset(); }}><Input name="code" placeholder="Code catégorie taxe" required /><Input name="label" placeholder="Libellé catégorie taxe" required /><Button type="submit" size="sm" disabled={createTaxCategory.isPending}>Ajouter une catégorie</Button></form><form className="grid gap-2" onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); createTaxType.mutate({ categoryId: String(data.get("categoryId")) || undefined, code: String(data.get("code")), label: String(data.get("label")) }); event.currentTarget.reset(); }}><select name="categoryId" className="h-9 rounded-md border border-input bg-background px-3 text-sm"><option value="">Sans catégorie</option>{catalog.data?.taxCategories.map(row => <option key={row.id} value={row.id}>{row.label}</option>)}</select><Input name="code" placeholder="Code taxe" required /><Input name="label" placeholder="Libellé taxe" required /><Button type="submit" size="sm" variant="outline" disabled={createTaxType.isPending}>Ajouter un type de taxe</Button></form><form className="grid gap-2" onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); createPeriodicity.mutate({ code: String(data.get("code")), label: String(data.get("label")), calendarUnit: String(data.get("calendarUnit")) as "DAY" | "WEEK" | "MONTH" | "QUARTER" | "SEMESTER" | "YEAR" | "CUSTOM", intervalCount: 1 }); event.currentTarget.reset(); }}><Input name="code" placeholder="Code périodicité" required /><Input name="label" placeholder="Libellé périodicité" required /><select name="calendarUnit" className="h-9 rounded-md border border-input bg-background px-3 text-sm"><option value="DAY">Jour</option><option value="WEEK">Semaine</option><option value="MONTH">Mois</option><option value="YEAR">Année</option></select><Button type="submit" size="sm" variant="outline" disabled={createPeriodicity.isPending}>Ajouter une périodicité</Button></form></div><div className="space-y-3 rounded-xl bg-[#f7f8f5] p-4"><p className="font-semibold text-[#173931]">Encaissement</p><form className="grid gap-2" onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); createPaymentMethod.mutate({ code: String(data.get("code")), label: String(data.get("label")), isCash: Boolean(data.get("isCash")) }); event.currentTarget.reset(); }}><Input name="code" placeholder="Code moyen" required /><Input name="label" placeholder="Libellé moyen" required /><label className="flex items-center gap-2 text-sm text-slate-600"><input type="checkbox" name="isCash" /> Encaissement en espèces</label><Button type="submit" size="sm" disabled={createPaymentMethod.isPending}>Ajouter un moyen</Button></form><Separator /><div className="space-y-1 text-sm text-slate-600"><p><strong>{catalog.data?.activityTypes.length ?? 0}</strong> type(s) d’activité</p><p><strong>{catalog.data?.taxTypes.length ?? 0}</strong> type(s) de taxe</p><p><strong>{catalog.data?.paymentMethods.length ?? 0}</strong> moyen(s) de paiement</p></div></div></div></CardContent></Card>
    {/* Les quatre collections partagent id et code ; le libellé est résolu selon le référentiel. */}
    <Card className="mb-5 border-[#dce8e3]"><CardHeader><CardTitle>Utilisateurs, rôles et permissions</CardTitle><CardDescription>Un utilisateur peut détenir plusieurs rôles. Les droits sont définis par module et par action, puis vérifiés à chaque procédure sensible.</CardDescription></CardHeader><CardContent><div className="grid gap-5 xl:grid-cols-3"><form className="grid content-start gap-2 rounded-xl bg-[#f7f8f5] p-4" onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); createRole.mutate({ code: String(data.get("code")), label: String(data.get("label")) }); event.currentTarget.reset(); }}><p className="font-semibold text-[#173931]">Créer un rôle</p><Input name="code" placeholder="Code (ex. COLLECTEUR)" required /><Input name="label" placeholder="Libellé du rôle" required /><Button type="submit" size="sm" disabled={createRole.isPending}>Ajouter le rôle</Button></form><form className="grid content-start gap-2 rounded-xl bg-[#f7f8f5] p-4" onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); createPermission.mutate({ module: String(data.get("module")), action: String(data.get("action")), label: String(data.get("label")) }); event.currentTarget.reset(); }}><p className="font-semibold text-[#173931]">Créer une permission</p><Input name="module" placeholder="Module (ex. payments)" required /><Input name="action" placeholder="Action (ex. create)" required /><Input name="label" placeholder="Libellé" required /><Button type="submit" size="sm" variant="outline" disabled={createPermission.isPending}>Ajouter la permission</Button></form><form className="grid content-start gap-2 rounded-xl bg-[#f7f8f5] p-4" onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); assignRole.mutate({ userId: Number(data.get("userId")), roleId: String(data.get("roleId")) }); }}><p className="font-semibold text-[#173931]">Affecter un rôle</p><select name="userId" required className="h-9 rounded-md border border-input bg-background px-3 text-sm"><option value="">Utilisateur</option>{adminUsers.data?.map(row => <option key={row.id} value={row.id}>{row.name || row.email || `Utilisateur #${row.id}`}</option>)}</select><select name="roleId" required className="h-9 rounded-md border border-input bg-background px-3 text-sm"><option value="">Rôle</option>{roles.data?.map(row => <option key={row.id} value={row.id}>{row.label}</option>)}</select><Button type="submit" size="sm" variant="outline" disabled={assignRole.isPending}>Affecter</Button></form></div><form className="mt-5 grid gap-3 rounded-xl border border-dashed border-[#c9d9d2] p-4 md:grid-cols-[1fr,2fr,auto] md:items-end" onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); setRolePermissions.mutate({ roleId: String(data.get("roleId")), permissionIds: data.getAll("permissionId").map(String) }); }}><div><Label>Rôle à paramétrer</Label><select name="roleId" required className="mt-1 h-10 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="">Sélectionner</option>{roles.data?.map(row => <option key={row.id} value={row.id}>{row.label}</option>)}</select></div><div><Label>Permissions accordées</Label><select name="permissionId" multiple className="mt-1 h-24 w-full rounded-md border border-input bg-background px-3 text-sm">{permissions.data?.map(row => <option key={row.id} value={row.id}>{row.module}.{row.action} · {row.label}</option>)}</select></div><Button type="submit" variant="outline" disabled={setRolePermissions.isPending}>Enregistrer les droits</Button></form><form className="mt-5 grid gap-3 rounded-xl border border-dashed border-[#c9d9d2] p-4 md:grid-cols-4 md:items-end" onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); assignTerritory.mutate({ userId: Number(data.get("userId")), territoryType: String(data.get("territoryType")) as "SECTOR" | "ZONE" | "MARKET" | "MARKET_LOCATION", territoryId: String(data.get("territoryId")), startDate: new Date(String(data.get("startDate"))) }); }}><div><Label>Utilisateur</Label><select name="userId" required className="mt-1 h-10 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="">Sélectionner</option>{adminUsers.data?.map(row => <option key={row.id} value={row.id}>{row.name || row.email || `Utilisateur #${row.id}`}</option>)}</select></div><div><Label>Type de périmètre</Label><select name="territoryType" required className="mt-1 h-10 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="SECTOR">Secteur</option><option value="ZONE">Zone</option><option value="MARKET">Marché</option><option value="MARKET_LOCATION">Emplacement</option></select></div><div><Label>Périmètre</Label><select name="territoryId" required className="mt-1 h-10 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="">Sélectionner un élément</option>{territoryItems.map(row => <option key={row.id} value={row.id}>{row.code} · {row.name || row.label}</option>)}</select></div><div><Label>Date de début</Label><Input name="startDate" type="date" defaultValue={new Date().toISOString().slice(0, 10)} required /><Button type="submit" size="sm" className="mt-2 w-full" variant="outline" disabled={assignTerritory.isPending}>Affecter le périmètre</Button></div></form></CardContent></Card>
    <div className="grid gap-5 lg:grid-cols-3"><Card className="border-[#dce8e3]"><CardHeader><div className="flex items-center justify-between"><ShieldCheck className="size-5 text-[#0f5a4e]" /><Badge variant="outline">Serveur</Badge></div><CardTitle className="mt-4">Accès contrôlés</CardTitle><CardDescription>Le modèle intègre des rôles multiples, des permissions module/action et des affectations géographiques historisées.</CardDescription></CardHeader></Card><Card className="border-[#dce8e3]"><CardHeader><div className="flex items-center justify-between"><RefreshCw className="size-5 text-[#0f5a4e]" /><Badge variant="outline">Idempotence</Badge></div><CardTitle className="mt-4">Synchronisation</CardTitle><CardDescription>{sync.data?.filter(row => row.status !== "SYNCED").length ?? 0} opération(s) en attente, en erreur ou en conflit.</CardDescription></CardHeader></Card><Card className="border-[#dce8e3]"><CardHeader><div className="flex items-center justify-between"><FileText className="size-5 text-[#0f5a4e]" /><Badge variant="outline">Append-only</Badge></div><CardTitle className="mt-4">Journal d’audit</CardTitle><CardDescription>{audit.data?.length ?? 0} événement(s) visibles pour les administrateurs autorisés.</CardDescription></CardHeader></Card></div>
    <Card className="mt-5 border-[#dce8e3]"><CardHeader><CardTitle>Dernières opérations sensibles</CardTitle><CardDescription>Ce journal est inséré par les services métier et ne comporte aucune opération de suppression dans l’interface.</CardDescription></CardHeader><CardContent>{audit.error ? <ErrorBlock message={audit.error.message} /> : !audit.data?.length ? <EmptyState icon={ShieldCheck} title="Aucune opération auditée" text="Les créations, fusions, paiements, validations et synchronisations seront consignés ici." /> : <Table><TableHeader><TableRow><TableHead>Horodatage</TableHead><TableHead>Module</TableHead><TableHead>Action</TableHead><TableHead>Entité</TableHead></TableRow></TableHeader><TableBody>{audit.data.map(row => <TableRow key={row.id}><TableCell>{new Date(row.createdAt).toLocaleString("fr-FR")}</TableCell><TableCell>{row.module}</TableCell><TableCell>{row.action}</TableCell><TableCell className="font-mono text-xs">{row.entityType}:{row.entityId.slice(0, 8)}</TableCell></TableRow>)}</TableBody></Table>}</CardContent></Card></>;
}

export function AdministrationPage() { return <AdministrationWorkspace />; }

export function ObligationsPage() {
  const obligations = trpc.municipal.taxation.obligations.useQuery();
  const [search, setSearch] = useState(""); const [status, setStatus] = useState("ALL");
  const visible = useMemo(() => (obligations.data ?? []).filter(({ obligation, taxpayer, activity }) => {
    const haystack = `${obligation.reference} ${taxpayer?.legalName ?? ""} ${taxpayer?.firstName ?? ""} ${taxpayer?.lastName ?? ""} ${activity?.label ?? ""}`.toLowerCase();
    return (status === "ALL" || obligation.status === status) && haystack.includes(search.trim().toLowerCase());
  }), [obligations.data, search, status]);
  const exportRows = buildObligationExportRows(visible);
  return <><PageTitle eyebrow="Recouvrement" title="Obligations fiscales" description="Suivez les obligations périodiques générées, leurs échéances, leurs montants restant dus et leur état de recouvrement." action={<ExportActions filename="echeancier-obligations" title="Échéancier des obligations" columns={OBLIGATION_EXPORT_COLUMNS} rows={exportRows} />} />
    <Card className="border-[#dce8e3]"><CardHeader><CardTitle>Échéancier des obligations</CardTitle><CardDescription>Les montants et les statuts sont mis à jour uniquement par les services métier d’encaissement et d’ajustement autorisés.</CardDescription></CardHeader><CardContent>{obligations.error ? <ErrorBlock message={obligations.error.message} /> : obligations.isLoading ? <p className="text-sm text-slate-500">Chargement…</p> : !obligations.data?.length ? <EmptyState icon={FileText} title="Aucune obligation générée" text="Affectez une règle fiscale à une activité, puis générez les obligations périodiques." /> : <><div className="mb-4 grid gap-3 md:grid-cols-[1fr,220px]"><div className="relative"><Search className="absolute left-3 top-3 size-4 text-slate-400" /><Input value={search} onChange={event => setSearch(event.target.value)} className="pl-9" placeholder="Rechercher par référence, redevable ou activité" /></div><select value={status} onChange={event => setStatus(event.target.value)} className="h-10 rounded-md border border-input bg-background px-3 text-sm"><option value="ALL">Tous les états</option>{Array.from(new Set((obligations.data ?? []).map(({ obligation }) => obligation.status))).map(value => <option key={value} value={value}>{value}</option>)}</select></div>{!visible.length ? <EmptyState icon={FileText} title="Aucun résultat" text="Modifiez votre recherche ou votre filtre d’état." /> : <div className="overflow-x-auto"><Table className="min-w-[940px]"><TableHeader><TableRow><TableHead>Référence</TableHead><TableHead>Redevable</TableHead><TableHead>Activité</TableHead><TableHead>Échéance</TableHead><TableHead>À payer</TableHead><TableHead>Restant</TableHead><TableHead>État</TableHead></TableRow></TableHeader><TableBody>{visible.map(({ obligation, taxpayer, activity }) => <TableRow key={obligation.id}><TableCell className="font-mono text-xs text-[#0f5a4e]">{obligation.reference}</TableCell><TableCell>{taxpayer?.legalName || `${taxpayer?.lastName ?? ""} ${taxpayer?.firstName ?? ""}`.trim() || "—"}</TableCell><TableCell>{activity?.label || "—"}</TableCell><TableCell>{dateText(obligation.dueDate)}</TableCell><TableCell>{money(obligation.expectedAmount)}</TableCell><TableCell className="font-semibold">{money(obligation.remainingAmount)}</TableCell><TableCell><Badge variant="outline" className="border-[#c9d9d2] bg-[#f7f8f5] text-[#173931]">{obligation.status}</Badge></TableCell></TableRow>)}</TableBody></Table></div>}</>}</CardContent></Card></>;
}

export function ReceiptsPage() {
  const receiptsQuery = trpc.municipal.receipts.list.useQuery(); const utils = trpc.useUtils();
  const [selectedReceiptId, setSelectedReceiptId] = useState<string | null>(null);
  const history = trpc.municipal.receipts.printHistory.useQuery({ receiptId: selectedReceiptId ?? "00000000-0000-4000-8000-000000000000" }, { enabled: Boolean(selectedReceiptId) });
  const reprint = trpc.municipal.payments.reprintReceipt.useMutation({ onSuccess: () => { toast.success("Réimpression enregistrée dans l’historique du reçu."); if (selectedReceiptId) utils.municipal.receipts.printHistory.invalidate({ receiptId: selectedReceiptId }); window.print(); }, onError: error => toast.error(error.message) });
  const selected = receiptsQuery.data?.find(row => row.receipt.id === selectedReceiptId);
  useEffect(() => {
    const nativePrint = window.print;
    window.print = () => {
      if (!selected) return nativePrint();
      const escapeHtml = (value: string | number | null | undefined) => String(value ?? "—").replace(/[&<>'"]/g, character => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;" })[character] ?? character);
      const taxpayerName = selected.taxpayer?.legalName || `${selected.taxpayer?.lastName ?? ""} ${selected.taxpayer?.firstName ?? ""}`.trim() || "—";
      const frame = document.createElement("iframe");
      frame.title = `Impression ${selected.receipt.reference}`;
      frame.setAttribute("aria-hidden", "true");
      frame.style.cssText = "position:fixed;right:0;bottom:0;width:1px;height:1px;border:0;opacity:0;pointer-events:none;";
      document.body.appendChild(frame);
      const doc = frame.contentDocument;
      if (!doc) { frame.remove(); return nativePrint(); }
      doc.open();
      doc.write(`<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>${escapeHtml(selected.receipt.reference)}</title><style>@page{size:80mm auto;margin:6mm}*{box-sizing:border-box}body{margin:0;color:#0f172a;font-family:Arial,sans-serif;font-size:11px}.receipt{width:68mm;margin:0 auto}.brand{border-bottom:2px solid #0f5cdb;padding-bottom:10px}.brand strong{display:block;color:#073b8c;font-size:15px;letter-spacing:.04em}.title{margin:14px 0 6px;text-align:center;color:#073b8c;font-size:17px;font-weight:800}.badge{display:inline-block;border-radius:999px;background:#eaf2ff;color:#073b8c;padding:4px 8px;font-weight:700}.amount{margin:14px 0;border-radius:10px;background:linear-gradient(135deg,#0a55c7,#1775e5);padding:14px;color:#fff;text-align:center;font-size:21px;font-weight:800}.line{display:flex;justify-content:space-between;gap:12px;border-bottom:1px dashed #cbd5e1;padding:7px 0}.label{color:#475569}.hash{margin-top:14px;overflow-wrap:anywhere;color:#475569;font-family:monospace;font-size:8px}.footer{margin-top:16px;border-top:1px solid #cbd5e1;padding-top:10px;text-align:center;color:#475569;font-size:9px}</style></head><body><main class="receipt"><header class="brand"><strong>MAIRIE DE LIBREVILLE</strong><span>Gestion des taxes municipales</span></header><h1 class="title">REÇU D’ENCAISSEMENT</h1><p style="text-align:center"><span class="badge">${escapeHtml(selected.receipt.status)}</span></p><div class="line"><span class="label">Référence</span><strong>${escapeHtml(selected.receipt.reference)}</strong></div><div class="line"><span class="label">Redevable</span><strong>${escapeHtml(taxpayerName)}</strong></div><div class="line"><span class="label">Date d’émission</span><strong>${escapeHtml(dateText(selected.receipt.issuedAt))}</strong></div><div class="amount">${escapeHtml(money(selected.payment.netAmount))}</div><div class="line"><span class="label">Paiement</span><strong>${escapeHtml(selected.payment.reference)}</strong></div><p class="hash"><strong>QR de contrôle :</strong> ${escapeHtml(selected.receipt.qrPayload)}</p><p class="hash"><strong>Empreinte d’intégrité :</strong> ${escapeHtml(selected.receipt.integrityHash)}</p><footer class="footer">Document final immuable · Toute réimpression est enregistrée.</footer></main></body></html>`);
      doc.close();
      frame.onload = () => { frame.contentWindow?.focus(); frame.contentWindow?.print(); window.setTimeout(() => frame.remove(), 1200); };
    };
    return () => { window.print = nativePrint; };
  }, [selected]);
  return <><PageTitle eyebrow="Pièces d’encaissement" title="Reçus immuables" description="Chaque reçu contient une empreinte d’intégrité et un QR de contrôle. Aucune modification ni suppression n’est disponible ; les réimpressions sont tracées." action={<ExportActions filename="registre-recus" title="Registre des reçus" columns={RECEIPT_EXPORT_COLUMNS} rows={buildReceiptExportRows(receiptsQuery.data ?? [])} />} />
    <div className="grid gap-5 xl:grid-cols-[1.65fr,1fr]"><Card className="border-[#dce8e3]"><CardHeader><CardTitle>Registre des reçus</CardTitle><CardDescription>Sélectionnez un reçu pour contrôler son empreinte, son QR et son historique d’impression.</CardDescription></CardHeader><CardContent>{receiptsQuery.error ? <ErrorBlock message={receiptsQuery.error.message} /> : receiptsQuery.isLoading ? <p className="text-sm text-slate-500">Chargement…</p> : !receiptsQuery.data?.length ? <EmptyState icon={ReceiptText} title="Aucun reçu émis" text="Les reçus définitifs sont générés à chaque encaissement validé." /> : <div className="overflow-x-auto"><Table><TableHeader><TableRow><TableHead>Référence</TableHead><TableHead>Redevable</TableHead><TableHead>Montant</TableHead><TableHead>Émis le</TableHead><TableHead /></TableRow></TableHeader><TableBody>{receiptsQuery.data.map(({ receipt, payment, taxpayer }) => <TableRow key={receipt.id} className={selectedReceiptId === receipt.id ? "bg-[#edf5f1]" : undefined}><TableCell className="font-mono text-xs text-[#0f5a4e]">{receipt.reference}</TableCell><TableCell>{taxpayer?.legalName || `${taxpayer?.lastName ?? ""} ${taxpayer?.firstName ?? ""}`.trim() || "—"}</TableCell><TableCell>{money(payment.netAmount)}</TableCell><TableCell>{dateText(receipt.issuedAt)}</TableCell><TableCell><Button type="button" size="sm" variant="outline" onClick={() => setSelectedReceiptId(receipt.id)}>Consulter</Button></TableCell></TableRow>)}</TableBody></Table></div>}</CardContent></Card>
      <Card className="border-[#dce8e3]"><CardHeader><CardTitle>Aperçu du reçu final</CardTitle><CardDescription>Consultez la pièce finale avant toute impression. La pièce est immuable ; chaque réimpression est tracée avant l’ouverture du dialogue d’impression.</CardDescription></CardHeader><CardContent>{!selected ? <EmptyState icon={ReceiptText} title="Sélectionnez un reçu" text="Choisissez une ligne dans le registre pour afficher son aperçu, sa preuve d’intégrité et ses actions d’impression." /> : <div className="space-y-4 text-sm"><div className="rounded-xl bg-[#f7f8f5] p-4"><p className="font-mono text-xs text-[#0f5a4e]">{selected.receipt.reference}</p><p className="mt-2 font-semibold text-[#173931]">{money(selected.payment.netAmount)} · {selected.receipt.status}</p><p className="mt-2 break-all text-xs text-slate-500">QR : {selected.receipt.qrPayload}</p><p className="mt-2 break-all text-xs text-slate-500">Empreinte : {selected.receipt.integrityHash}</p></div><Button className="w-full" variant="outline" onClick={() => reprint.mutate({ receiptId: selected.receipt.id, deviceId: getDeviceId() })} disabled={reprint.isPending}>{reprint.isPending ? "Préparation de l’impression…" : "Imprimer ce reçu après aperçu"}</Button><Separator /><p className="font-semibold text-[#173931]">Historique d’impression</p>{history.isLoading ? <p className="text-slate-500">Chargement…</p> : !history.data?.length ? <p className="text-slate-500">Aucune impression enregistrée.</p> : <div className="space-y-2">{history.data.map(item => <div key={item.id} className="rounded-lg border border-[#e2ebe7] p-3"><p className="font-medium">{item.printType}</p><p className="mt-1 text-xs text-slate-500">{new Date(item.printedAt).toLocaleString("fr-FR")}</p></div>)}</div>}</div>}</CardContent></Card></div></>;
}

export function SyncPage() {
  const operations = trpc.municipal.sync.status.useQuery(); const conflicts = trpc.municipal.sync.conflicts.useQuery(); const utils = trpc.useUtils(); const offline = useOfflineQueue();
  const resolve = trpc.municipal.sync.resolveConflict.useMutation({ onSuccess: (_, input) => { if (input.resolution !== "MANUAL") { const op = conflicts.data?.find(row => row.conflict.id === input.conflictId)?.operation; if (op) offline.acknowledge(op.operationId); } toast.success(input.resolution === "MANUAL" ? "Conflit conservé pour traitement manuel et audité." : "Décision de conflit enregistrée et file locale acquittée."); utils.municipal.sync.conflicts.invalidate(); utils.municipal.sync.status.invalidate(); }, onError: error => toast.error(error.message) });
  return <><PageTitle eyebrow="Continuité terrain" title="Synchronisation hors connexion" description="La file locale utilise des identifiants d’opération idempotents. Les divergences sont journalisées puis résolues explicitement par un utilisateur autorisé." />
    <div className="grid gap-5 lg:grid-cols-3"><Card className="border-[#dce8e3]"><CardHeader><CardDescription>ÉTAT LOCAL</CardDescription><CardTitle className="text-3xl">{offline.online ? "En ligne" : "Hors connexion"}</CardTitle></CardHeader><CardContent><p className="text-sm text-slate-600">{offline.queueSize} opération(s) stockée(s) sur cet appareil.</p></CardContent></Card><Card className="border-[#dce8e3]"><CardHeader><CardDescription>ÉTAT SERVEUR</CardDescription><CardTitle className="text-3xl">{operations.data?.filter(row => row.status !== "SYNCED").length ?? 0}</CardTitle></CardHeader><CardContent><p className="text-sm text-slate-600">Opération(s) en attente, en échec ou en conflit.</p></CardContent></Card><Card className="border-[#dce8e3]"><CardHeader><CardDescription>CONFLITS OUVERTS</CardDescription><CardTitle className="text-3xl">{conflicts.data?.filter(row => row.conflict.resolution === "PENDING").length ?? 0}</CardTitle></CardHeader><CardContent><p className="text-sm text-slate-600">Une décision explicite est exigée pour chaque divergence.</p></CardContent></Card></div>
    <Card className="mt-5 border-[#dce8e3]"><CardHeader><CardTitle>Conflits de synchronisation</CardTitle><CardDescription>« Conserver serveur » confirme l’état serveur et retire l’opération locale correspondante. Les autres décisions restent visibles dans le journal d’audit.</CardDescription></CardHeader><CardContent>{conflicts.error ? <ErrorBlock message={conflicts.error.message} /> : !conflicts.data?.length ? <EmptyState icon={RefreshCw} title="Aucun conflit détecté" text="Les répétitions avec le même identifiant et le même contenu restent idempotentes." /> : <div className="space-y-3">{conflicts.data.map(({ conflict, operation }) => <div key={conflict.id} className="rounded-xl border border-[#dce8e3] p-4"><div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between"><div><p className="font-mono text-xs text-[#0f5a4e]">{operation.operationId}</p><p className="mt-1 font-semibold text-[#173931]">{operation.entityType} · {operation.operation}</p><p className="mt-1 text-xs text-slate-500">Créé le {new Date(conflict.createdAt).toLocaleString("fr-FR")} · Résolution : {conflict.resolution}</p></div>{conflict.resolution === "PENDING" && <div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={() => resolve.mutate({ conflictId: conflict.id, resolution: "SERVER" })} disabled={resolve.isPending}>Conserver serveur</Button><Button size="sm" variant="outline" onClick={() => resolve.mutate({ conflictId: conflict.id, resolution: "LOCAL" })} disabled={resolve.isPending}>Conserver local</Button><Button size="sm" onClick={() => resolve.mutate({ conflictId: conflict.id, resolution: "MANUAL" })} disabled={resolve.isPending}>À traiter manuellement</Button></div>}</div></div>)}</div>}</CardContent></Card></>;
}
